\begin{lemma}[Moment bound for a fixed outcome after $t$ queries]
\label{lem:fixed-outcome-concentration}
Let $\mathcal A$ be an arbitrary $r$-query quantum algorithm, and let $e$ be
any measurement event. For $x\sim\{-1,1\}^N$ uniform, define
\[
    p_e(x):=\Pr[\mathcal A^x \in e],
    \qquad
    \overline p_e:=\mathbb E_x[p_e(x)].
\]
Then for every integer $s\ge 1$,
\[
    \mathbb E_x[p_e(x)^s]
    \le
    (2s-1)^{rs}\,\overline p_e^{\,s}.
\]
Equivalently,
\[
    \left(\mathbb E_x[p_e(x)^s]\right)^{1/s}
    \le
    (2s-1)^r\,\overline p_e .
\]

\end{lemma}

\begin{proof}
Let $\Pi_e$ be the projector corresponding to event $e$, and set
\[
    F_e(x):=\Pi_e|\psi_r^x\rangle .
\]
By Theorem~\ref{thm:adaptive-polynomial-representation}, $F_e$ is a
vector-valued multilinear polynomial of degree at most $r$. Also
\[
    p_e(x)=\|F_e(x)\|_2^2.
\]
By vector-valued hypercontractivity (Theorem \ref{vec:bonami-beckner}) applied with moment $2s$,
\[
    \mathbb E_x\left[\|F_e(x)\|_2^{2s}\right]
    \le
    (2s-1)^{rs}
    \left(\mathbb E_x\left[\|F_e(x)\|_2^2\right]\right)^s.
\]
Substituting $\|F_e(x)\|_2^2=p_e(x)$ gives
\[
    \mathbb E_x[p_e(x)^s]
    \le
    (2s-1)^{rs}\,\overline p_e^{\,s}.
\]
Taking $s$-th roots gives the equivalent formulation.
