\label{sec:good_coupling_exits}

Recall that  $O_X$  is a $(1-\delta)$-dense distribution over oracles $O: [N]\rightarrow \{0,1\}$ and $O_U$ is the uniform distribution. 
We will show that it is possible to change a small fraction of the oracle \footnote{By a small fraction of the oracle, we mean a small fraction of the coordinates $i \in [N]$.} drawn from $O_X$ to make the distribution identical to the uniform distribution over oracles $O_U$. Here 'change' means flipping the output of the oracle at some inputs. 

We start by giving the following weaker theorem \Cref{changeoracle} comparing to \Cref{thm:strongchangeoracle}; based on which, we will prove \Cref{thm:strongchangeoracle}. The theorem gives an expected total modification, rather than per-coordinate. 

\begin{theorem} \label{changeoracle}
Let $O_X$ be any $(1-\delta)$-dense oracle distribution and $O_U$ be a uniform oracle distribution. There is a random algorithm $M$ that takes an oracle $O$ from $O_X$, 
chooses a set $\text{Flip}_{O, M} \subseteq [N]$, and flips the answer of $O$ on $\text{Flip}_{O, M}$ such that the output oracle distribution $M(O)$ (when $O \gets O_X$) is distributed
identically to the uniform oracle distribution $O_U$, where the randomness is taken over $O \sim O_X$ and the randomness of $M$. The expected size of $\text{Flip}_{O, M}$ is 
\begin{equation*}
	\mathbb{E}\left[|\text{Flip}_{O, M}|\right] \leq \sqrt{\frac{\ln 2}{2} \delta} \cdot N
\end{equation*}
where the randomness is taken over $O \sim O_X$ and the randomness of $M$. 
\end{theorem}

\begin{proof}
We view each of the oracles $O \sim O_X$ as a binary string of length $N$. Therefore, we can view the $(1-\delta)$ dense distribution over oracles, $O_X$, as $N$ joint binary random variables
$X_1, X_2, \cdots, X_N$. 

We will introduce some notation for simplicity: for any $0 \leq n \leq N$ and any $x \in \{0, 1\}^n$, let $p_x = \Pr[X_1 = x_1, \cdots, X_n = x_n]$. It is easy to see
that $p_{\emptyset} = 1$ and for any $x \in \{0,1\}^N$, $p_x \leq 2^{-(1-\delta) N}$ because the distribution $O_X$ is $(1-\delta)$ dense. Moreover, as an immediate consequence of its denseness, we have that for every $S \subseteq [N]$, the min-entropy $H_\infty(X_S) \geq (1-\delta) |S|$. 

Consider the following procedure which  generates any joint binary distribution: 
\begin{enumerate}
\item Let $p_{\emptyset} = 1$. 
\item For $n = 0, \cdots, N-1$, 
	\begin{itemize}
		\item  For any $x \in \{0, 1\}^{n}$,   choose $0 \leq q_{x, 0} \leq 1$ and $q_{x, 1} = 1 - q_{x, 0}$; 
		\item Let $p_{x||0} = p_x q_{x, 0}$ and  $p_{x||1} = p_x q_{x, 1}$; 
	\end{itemize}
\end{enumerate}
It is easy to see that $\{p_x\}$ for $x \in \{0, 1\}^n$ is a marginal distribution of $X_1, X_2, \cdots, X_n$. 

\begin{ob}
The sum of all the marginal distributions is $N$: 
\begin{equation*}
	\sum_{n=0}^{N-1} \sum_{x \in \{0,1\}^n } p_x =\sum_{n=0}^{N-1} 1 = N
\end{equation*}
\end{ob}

\begin{ob}
$X_1, X_2, \cdots, X_N$ has entropy at least $(1 - \delta) N$. 
\begin{equation*}
	H(X_1, X_2, \cdots, X_N) = - \sum_{x \in \{0,1\}^N } p_x \log_2(p_x) \geq  (1 - \delta) N  \cdot \sum_{x \in \{0,1\}^N } p_x =  (1 - \delta) N 
\end{equation*}
Besides, for any subset $S \subseteq [N]$, $H(X_S) \geq (1 - \delta) |S|$. 
\end{ob}

Given the above procedure to generate the distribution $X_1, X_2, \cdots, X_N$, the following randomized algorithm $M$  changes the random variables and 
the resulting distribution is a uniform distribution over $\{0,1\}^N$.
\begin{algorithm}\caption{Modification Algorithm $M$}\label{alg:ModificationalgM}
\begin{algorithmic}
\State \textbf{Input:} $O = (x_1,\dots,x_N) \sim O_X \subseteq \{0,1\}^N$. 

\For{$n = 0, \dots N-1$}
    \State Let $x^{(n)} := (x_1,\dots,x_n)$ be the length $n$  prefix of $O$. Note that $x^{(0)}= \varepsilon$, the empty string.
    \State Let $p_{x^{(n)}} := \Pr[(X_1,\dots X_n) = x^{(n)}]$.
    \State Let $b := x_{n+1}$
    \State Define
        \[q_{x^{(n)},b} := \Pr[X_{n+1} = b \mid (X_1,\dots X_n) = x^{(n)}]
    \]
    \State (Equivalently, $p_{x^{(n)}\| b} = p_{x^{(n)}} \cdot q_{x^{(n)},b}$)
    \If{$q_{x^{(n)},b} > \tfrac{1}{2}$} 
        \State Set  $\tilde{X}_{n+1}$ to $1-b$ with probability $\frac{q_{x^{(n)},b} - 1/2}{q_{x^{(n)},b}}$, otherwise set $\tilde{X}_{n+1}$ to $b$.
        \Else 
    \State Set $\tilde X_{n+1} \gets b$
 \EndIf
\EndFor
\State \textbf{Output:}  $\tilde{O} = (\tilde{X}_1, \dots \tilde{X}_N)$
\end{algorithmic}
\end{algorithm}

\begin{lemma}
Algorithm $M$ outputs the  uniform distribution $O_U$ over $\{0,1\}^N$. 
\end{lemma}
\begin{proof}
We prove that for all $n\in \{0, \dots N-1\}$, after round $n$, the modified random variable
$\tilde{X}_{n+1}$ is uniform and independent of the prefix
$X^{(n)} := (X_1,\dots,X_n)$. Fix any prefix $x \in \{0,1\}^n$. Recall that
\[
q_{x,b} := \Pr[X_{n+1} = b \mid X^{(n)} = x].
\]
Let $\tilde{X}_{n+1}$ denote the output of the $n^{th}$ iteration of Algorithm \ref{alg:ModificationalgM}.

Recall that $x_{n+1}=b$, and without loss of generality, we can assume that
For every $x$ and $b$ such that $q_{x, b} \geq 1/2$, the algorithm flips $b$ to $1-b$ with probability $\frac{q_{x,b}-1/2}{q_{x,b}}$. Hence, 
\begin{align*}
     \Pr[X^{(n)}=x \wedge \tilde{X}_{n+1}=b] = \Pr[X^{(n)}=x \wedge X_{n+1}=b]\cdot \frac{1/2}{q_{x,b}}

     = p_x \cdot \frac{1}{2}.
\end{align*}

This implies that $\Pr[X^{(n)}=x \wedge \tilde{X}_{n+1}=1-b]= p_x \cdot \frac{1}{2}$ as well. 
\noindent
In both cases,
\[
\Pr[\tilde{X}_{n+1} = b \wedge X^{(n)} = x] = \frac{1}{2} \cdot \Pr[X^{(n)}=x].
\]
Thus $\tilde{X}_{n+1}$ is uniform and independent of $X^{(n)}$.
Since each $\tilde{X}_i$ depends only on $X^{(i)}$, it follows inductively that
$(\tilde{X}_1,\dots,\tilde{X}_N)$ is uniform over $\{0,1\}^N$.
\end{proof}
\noindent Next, we will prove that \begin{equation*}
	\mathbb{E}\left[|\text{Flip}_{O, M}|\right] \leq \sqrt{\ln 2 / 2 \cdot \delta} \cdot N
\end{equation*}
where  the randomness is taken over $O \sim O_X$ and the randomness of $M$. We begin by making the following observations:

\begin{ob}
For all $n \in \{0, \dots N-1\}$, and for all prefixes $x \in \{0,1\}^n$ of length $n$, define $e_x = |q_{x, 0} - 1/2| = |q_{x, 1} - 1/2|$.  The expected number of modifications at step $n$ of Algorithm \ref{alg:ModificationalgM} is the following:
\begin{eqnarray*}
\sum_{x:  q_{x, b} > 1/2} \Pr\left[ X_{[n]} = x, X_{n+1} = b \right] \cdot \left( \frac{q_{x, b} - 1/2}{q_{x, b}} \right) = \sum_{x \in \{0,1\}^n } p_x e_x
\end{eqnarray*}
So the expected total number of modifications is $\sum_{n=0}^{N-1}  \sum_{x \in \{0,1\}^n } p_x e_x$. 
\end{ob}

\begin{lemma}
\begin{equation*}
	\sum_{n=0}^{N-1}  \sum_{x \in \{0,1\}^n }  p_x e^2_x \leq \frac{\ln 2}{2} \delta \cdot N
\end{equation*}
\end{lemma}
\begin{proof}
	Consider the difference between $H(X_1, X_2, \cdots, X_{n+1})$ and $H(X_1, \cdots, X_n)$, 
\begin{eqnarray*}
	H(X^{(n+1)}) - H(X^{(n)}) &=& \sum_{x} p_x \log_2(p_x) -  \sum_{x, b} p_x q_{x, b} \log_2(p_x q_{x, b})  \\
			&=& - \sum_{x, b} p_x \left( q_{x, 0} \log_2(q_{x, 0}) + q_{x, 1} \log_2(q_{x, 1})  \right)  = \sum_x p_x H_b(q_{x, 0})
\end{eqnarray*}
where $H_b$ is the binary entropy function $H_b(x) = 1 - \frac{1}{2 \ln 2} \sum_{n \geq 1} \frac{(1 - 2 x)^{2 n}}{n (2 n - 1)} \leq 1 - \frac{2}{\ln 2} |x - 1/2|^2$. 
It implies $ \sum_x p_x H_b(q_{x, 0}) \leq 1 - \sum_x p_x \cdot \frac{2}{\ln 2} e_x^2$. 
Summing over $n$, the LHS evaluates to  
\[
\sum_{i=0}^{N}H(X^{(i+1)})-H(X^{(i)})= H(X^{(N)})
\]
Thus, we have that 
\begin{eqnarray*}
	(1-\delta) N \leq H(X^{(N)}) = \sum_{n=0}^{N-1} \sum_{x \in \{0,1\}^n } p_x H_b(q_{x, 0}) \leq N - \sum_{n=0}^{N-1} \sum_{x \in \{0,1\}^n } p_x \cdot \frac{2}{\ln 2} e_x^2
\end{eqnarray*}
Our lemma follows. 
\end{proof}

By Cauchy-Schwarz inequality, we have 
\begin{eqnarray*}
	\left(\sum_{n=0}^{N-1}  \sum_{x \in \{0,1\}^n } p_x e_x\right)^2 &\leq& \left( \sum_n \sum_x (\sqrt{p_x})^2 \right) \cdot \left( \sum_n \sum_x (\sqrt{p_x} e_x)^2 \right)  \\
		&\leq&  \frac{\ln 2}{2} \delta N^2
\end{eqnarray*} 
which implies that 
\[
\sum_{n=0}^{N-1}  \sum_{x \in \{0,1\}^n } p_x e_x\leq N \sqrt{\frac{\ln 2}{2}\cdot \delta}
\]
Our theorem follows. 
\end{proof}

\begin{corollary} \label{changeoracleanyorder}
Let $O \sim O_X$, where $O_X$ is a $(1-\delta)$-dense oracle distribution.
Let $M_{\pi}$ be the same as Algorithm \ref{alg:ModificationalgM}, but it executes according to the ordering specified by the permutation $\pi$: $\pi(0), \pi(1), \cdots, \pi(N-1)$. 
Let $\text{Flip}_{O, M_{\pi}, j} \subseteq \{\pi(0), \pi(1), \cdots, \pi(j-1)\}$ be the set that $M_{\pi}$ modifies 
in the first $j$ rounds on input $O \sim O_X.$ We have for every permutation $\pi$,  for every $0 \leq j < N$, 
\begin{equation*}
	\mathbb{E}\left[ |\text{Flip}_{O, M_{\pi}, j} | \right] \leq \sqrt{\frac{\ln 2}{2} \delta} \cdot j
\end{equation*}
The randomness is taken over $O \sim O_X$ and the random coins of $M_{\pi}$. 

When $\pi$ is an identity permutation and $j = N - 1$, it is equivalent to {Theorem \ref{changeoracle}}. 
\end{corollary}
\begin{proof}
   Since $O_X$ is a $(1-\delta)$ dense distribution, by definition, for all subsets $S$ of size up to $N$, 
 the min entropy of $O_X$ restricted to coordinates in $S$ is lower bounded by $(1-\delta)\cdot |S|$.  Furthermore, since this is the only guarantee required for the proof of \Cref{changeoracle}, the same  proof works.
\end{proof}

Now we will prove a stronger version of Theorem \ref{changeoracle}, which says that, informally, there exists a modification algorithm which takes as input $O \sim O_X$, and outputs an oracle distribution according to $O_U$, with the stronger guarantee that \emph{all} coordinates $i \in [N]$ are flipped with small probability over the choice of $O \sim O_X$, and the randomness of the modification algorithm. 
\begin{theorem} [A stronger version of Theorem \ref{changeoracle}]  \label{strongchangeoracle}
For any $(1-\delta)$-dense oracle distribution $O_X$, there exists a randomized algorithm $M^*$ where $M^*$ such that if $O \sim O_X$, then $M^*(O)$ is distributed as $O_U$,  and for every $i \in \{1, \cdots, N\}$, 
$M^*$ modifies $O(i)$ with probability at most $\sqrt{\frac{\ln 2}{2} \cdot \delta} + o(1)$ where $o(1)$ can be any arbitrarily small number.  
\end{theorem}

Before proving the theorem, we present its symmetric counterpart, which transforms $O_U$ into $O_X$.
\begin{corollary}\label{uniformtodenseM}
      For all $(1-\delta)$ dense distributions $O_X$ over oracles $O:[N]\rightarrow \{0,1\}$,  there exists an algorithm $M_U^*$  such that if $O \sim O_U$ which is the uniform distribution over oracles $O:[N]\rightarrow \{0,1\}$, then $M_U^*(O)$ is distributed according to  $O_X$, and for every $i \in \{1 \dots N\}$, $M_U^*(O)$ modifies $O(i)$ with probability at most $\sqrt{\frac{\ln 2}{2}\cdot \delta}+o(1)$ where $o(1)$ can be any arbitrarily small number.   
\end{corollary}
\begin{proof}
    Let $c_{O, O'}$ be the probability that $O$ is sampled from $O_X$ and it is coupled/modified into $O'$ as in \Cref{strongchangeoracle}. Since it is symmetric, we can also define $M^*_U$ by $c_{O, O'}$; $c_{O, O'}$ defines the probability that $O'$ is sampled from $O_U$ and it is coupled/modified into $O$.

    Clearly, for every $i \in [N]$, 
    \begin{align*}
        \sqrt{\frac{\ln 2}{2} \delta} + o(1) \geq \Pr_{O\sim O_X}[M^* \text{ flips } O(i)] = \sum_{\substack{O, O'\\ O(i) \ne O'(i)}} c_{O, O'} = \Pr_{O'\sim O_U}[M_U^* \text{ flips } O'(i)].
    \end{align*}
\end{proof}

